helpers.CronClockSchedule:
public class CronClockSchedule implements Schedulable {
 public class ClockCaptureException extends Exception {}
 private Boolean callback;
 public CronClockSchedule(){callback=false;}
 public CronClockSchedule(Boolean value){callback=value;}
 public void execute(SchedulableContext context){
  if(callback){
   Id owned=context.getTriggerId();
   List<CronTrigger> selected=[SELECT Id,NextFireTime,StartTime,PreviousFireTime,EndTime,CronExpression,TimeZoneSidKey,State,TimesTriggered FROM CronTrigger WHERE Id=:owned];
   if(selected.size()!=1 || selected[0].Id!=owned){throw new ClockCaptureException('FIXTURE_CALLBACK_SCOPE');}
   Map<String,Object> v=fields(selected[0],false);
   v.put('triggerIdQueryMatched',true);
   v.put('context',facts());
   throw new ClockCaptureException('CRON_CALLBACK|'+JSON.serialize(v));
  }
 }
 public static List<String> facts(){
  Id uid=UserInfo.getUserId();Id oid=UserInfo.getOrganizationId();
  User u=[SELECT TimeZoneSidKey FROM User WHERE Id=:uid];
  Organization org=[SELECT TimeZoneSidKey FROM Organization WHERE Id=:oid];
  return new List<String>{u.TimeZoneSidKey,UserInfo.getTimeZone().getID(),org.TimeZoneSidKey};
 }
 public static Map<String,Object> afterStop(String job){
  Id owned=job;
  List<CronTrigger> selected=[SELECT Id,NextFireTime,StartTime,PreviousFireTime,EndTime,CronExpression,TimeZoneSidKey,State,TimesTriggered FROM CronTrigger WHERE Id=:owned];
  Map<String,Object> v=new Map<String,Object>{'rows'=>selected.size(),'stopReturned'=>true,'context'=>facts(),'callbackContext'=>null};
  Integer outOfScope=0;for(CronTrigger c:selected){if(c.Id!=owned){outOfScope++;}}
  v.put('outOfScope',outOfScope);
  if(selected.size()==1 && outOfScope==0){
   v.put('state',selected[0].State);v.put('count',selected[0].TimesTriggered);
   if(selected[0].TimesTriggered>0){v.put('effect','fired-exception-swallowed');}
   else{v.put('effect','fire-unconfirmed-counter-zero');v.put('status','FIXTURE_CALLBACK_COUNTER_ZERO');}
  }else{v.put('effect','unconfirmed-trigger-absent');v.put('status','FIXTURE_CALLBACK_READBACK');}
  return v;
 }
 public static Object clock(Datetime d,Boolean formats){
  if(d==null){return null;}
  String iso=d.formatGmt('yyyy-MM-dd\'T\'HH:mm:ss.SSS\'Z\'');
  if(formats){return new List<Object>{iso,d.format('yyyy-MM-dd HH:mm:ss','GMT'),d.format('yyyy-MM-dd HH:mm:ss','America/Los_Angeles'),d.format('yyyy-MM-dd HH:mm:ss','Asia/Kolkata')};}
  Long adjusted=Datetime.newInstanceGmt(d.yearGmt(),d.monthGmt(),d.dayGmt(),d.hourGmt(),d.minuteGmt(),d.secondGmt()).getTime()+Math.mod(d.getTime(),1000);
  return new List<Object>{iso,d.getTime(),adjusted};
 }
 public static Map<String,Object> fields(CronTrigger c,Boolean formats){
  Map<String,Object> v=new Map<String,Object>();
  v.put('times',new List<Object>{clock(c.NextFireTime,formats),clock(c.StartTime,formats),clock(c.PreviousFireTime,formats),clock(c.EndTime,formats)});
  v.put('cron',c.CronExpression);
  if(!formats){v.put('zone',c.TimeZoneSidKey);v.put('state',c.State);v.put('count',c.TimesTriggered);}
  return v;
 }
 public static Map<String,Object> sample(String name,String expression,Integer minutes,Integer scope,String measurement){
  Boolean formats=measurement=='formats';
  Map<String,Object> v=new Map<String,Object>{'context'=>facts()};
  String job=null,step='schedule';Datetime before=Datetime.now();
  try{
   if(minutes==null){job=System.schedule(name,expression,new CronClockSchedule());}
   else if(scope==null){job=System.scheduleBatch(new CronClockBatch(),name,minutes);}
   else{job=System.scheduleBatch(new CronClockBatch(),name,minutes,scope);}
   Datetime after=Datetime.now();step='query';Id owned=job;
   List<CronTrigger> selected=[SELECT Id,NextFireTime,StartTime,PreviousFireTime,EndTime,CronExpression,TimeZoneSidKey,State,TimesTriggered FROM CronTrigger WHERE Id=:owned];
   Integer outOfScope=0;for(CronTrigger c:selected){if(c.Id!=owned){outOfScope++;}}
   if(selected.size()!=1 || outOfScope!=0){v.put('status','FIXTURE_QUERY_SCOPE');}
   else{
    CronTrigger c=selected[0];
    if(measurement=='local'){
     v.put('cron',c.CronExpression);
     if(c.NextFireTime==null){v.put('nextLocal',null);}
     else{v.put('nextLocal',new List<Object>{c.NextFireTime.formatGmt('yyyy-MM-dd\'T\'HH:mm:ss.SSS\'Z\''),c.NextFireTime.getTime(),c.NextFireTime.format('yyyy-MM-dd HH:mm:ss'),c.NextFireTime.format(),String.valueOf(c.NextFireTime)});}
    }else{v.putAll(fields(c,formats));}
    v.put('window',new List<Long>{before.getTime(),after.getTime()});
    if(measurement=='observe' && c.NextFireTime!=null){v.put('deltaMs',c.NextFireTime.getTime()-before.getTime());v.put('gmtMinute',c.NextFireTime.format('mm','GMT'));}
   }
  }catch(Exception e){v.put('step',step);if(step!='schedule'){v.put('status','FIXTURE_MEASUREMENT');}v.put('exceptionType',e.getTypeName());v.put('exceptionMessage',e.getMessage());}
  finally{if(job!=null){try{System.abortJob(job);}catch(Exception cleanup){v.put('cleanup','abort-failed');}}}
  return v;
 }
}

